\n-- All exam sessions visible without login: for fictitious DEMO students only.\ncreate or replace function public.es_demo_list_sessions()\nreturns table(code text,level text,group_name text,exam_name text,exam_date date,students jsonb,created_at timestamptz)\nlanguage sql security definer set search_path='' as $$\n select s.code,s.level,s.group_name,s.exam_name,s.exam_date,s.students,s.created_at\n from public.es_demo_sessions_shared s order by s.created_at desc limit 100;\n$$;\nrevoke all on function public.es_demo_list_sessions() from public;\ngrant execute on function public.es_demo_list_sessions() to anon,authenticated;\n